named_expression <- function(words) {
  if (length(words) < 2L || !endsWith(words[[1L]], ":")) return(NULL)
  name <- substr(words[[1L]], 1L, nchar(words[[1L]]) - 1L)
  terms <- parse_expression(words[-1L])
  if (lp_name(name) && !is.null(terms)) list(name = name, terms = terms) else NULL
}
parse_constraint <- function(words, line) {
  size <- length(words)
  if (size < 4L || !words[[size - 1L]] %in% c("<=", ">=", "=")) return(NULL)
  rhs <- read_number(words[[size]], TRUE)
  named <- named_expression(head(words, -2L))
  if (is.null(rhs) || is.null(named)) return(NULL)
  list(line = line, name = named$name, terms = named$terms, comparison = words[[size - 1L]], rhs = rhs)
}
parse_block <- function(name, body, end_line) {
  parsed <- list(name = name, error = NULL, direction = NULL, objective = NULL,
                 constraints = list(), bounds = list(), integers = list(), binaries = list())
  state <- "A"
  for (record in body) {
    line <- record$line
    text <- record$text
    words <- strsplit(text, " ", fixed = TRUE)[[1L]]
    accepted <- FALSE
    if (state == "A" && text %in% c("maximize", "minimize")) {
      parsed$direction <- text
      state <- "B"
      accepted <- TRUE
    } else if (state == "B") {
      named <- named_expression(words)
      if (!is.null(named)) {
        parsed$objective <- named$terms
        state <- "C"
        accepted <- TRUE
      }
    } else if (state == "C" && text == "subject to") {
      state <- "D"
      accepted <- TRUE
    } else if (state %in% c("D", "E")) {
      if (state == "E" && text %in% c("bounds", "integer", "binary")) {
        state <- switch(text, bounds = "F", integer = "G", binary = "H")
        accepted <- TRUE
      } else {
        item <- parse_constraint(words, line)
        if (!is.null(item)) {
          parsed$constraints[[length(parsed$constraints) + 1L]] <- item
          state <- "E"
          accepted <- TRUE
        }
      }
    }
    if (!accepted) {
      parsed$error <- list(line = line, message = "syntax error")
      return(parsed)
    }
  }
  if (state %in% c("A", "B", "C", "D")) parsed$error <- list(line = end_line, message = "syntax error")
  parsed
}
read_models <- function() {
  records <- readLines("input/models.lp", warn = FALSE)
  models <- body <- list()
  name <- NULL
  for (line in seq_along(records)) {
    text <- records[[line]]
    if (!nzchar(text) || startsWith(text, "#")) next
    if (is.null(name)) {
      name <- strsplit(text, " ", fixed = TRUE)[[1L]][[2L]]
      body <- list()
    } else if (text == "end") {
      models[[length(models) + 1L]] <- parse_block(name, body, line)
      name <- NULL
    } else {
      body[[length(body) + 1L]] <- list(line = line, text = text)
    }
  }
  models
}
run_phase <- function(tableau, costs, candidates, objective) {
  iterations <- 0L
  lines <- character()
  candidates <- sort(candidates)
  repeat {
    reduced <- reduced_costs(tableau, costs)
    eligible <- candidates[vapply(candidates, function(column) reduced[[column]] < 0, logical(1L))]
    if (!length(eligible)) return(list(iterations = iterations, unbounded = NULL, lines = lines))
    column <- eligible[[1L]]
    row <- NULL
    ratio <- NULL
    for (candidate in seq_along(tableau$values)) {
      value <- tableau$values[[candidate]][[column]]
      if (value <= 0) next
      candidate_ratio <- tableau$rhs[[candidate]] / value
      if (is.null(row) || candidate_ratio < ratio || (candidate_ratio == ratio && tableau$basic[[candidate]] < tableau$basic[[row]])) {
        row <- candidate
        ratio <- candidate_ratio
      }
    }
    if (is.null(row)) return(list(iterations = iterations, unbounded = column, lines = lines))
    leaving <- tableau$basic[[row]]
    before <- reduced[[column]]
    pivot(tableau, row, column)
    iterations <- iterations + 1L
    value <- objective(phase_value(tableau, costs))
    lines <- c(lines, paste("PIVOT", iterations, "enter", tableau$column_names[[column]], "reduced", fraction_text(before), "leave", tableau$column_names[[leaving]], "row", tableau$row_names[[row]], "ratio", fraction_text(ratio), "objective", fraction_text(value)))
  }
}
new_tableau <- function(form) {
  list2env(list(row_names = form$row_names, column_names = form$column_names,
               values = form$matrix, rhs = form$rhs, basic = form$initial), parent = emptyenv())
}
pivot <- function(tableau, row, column) {
  divisor <- tableau$values[[row]][[column]]
  tableau$values[[row]] <- lapply(tableau$values[[row]], function(value) value / divisor)
  tableau$rhs[[row]] <- tableau$rhs[[row]] / divisor
  for (other in seq_along(tableau$values)) {
    if (other == row) next
    factor <- tableau$values[[other]][[column]]
    tableau$values[[other]] <- Map(function(value, pivot_value) value - factor * pivot_value, tableau$values[[other]], tableau$values[[row]])
    tableau$rhs[[other]] <- tableau$rhs[[other]] - factor * tableau$rhs[[row]]
  }
  tableau$basic[[row]] <- column
}
reduced_costs <- function(tableau, costs) {
  lapply(seq_along(costs), function(column) {
    costs[[column]] - qsum(lapply(seq_along(tableau$basic), function(row) costs[[tableau$basic[[row]]]] * tableau$values[[row]][[column]]))
  })
}
phase_value <- function(tableau, costs) qsum(lapply(seq_along(tableau$basic), function(row) costs[[tableau$basic[[row]]]] * tableau$rhs[[row]]))
fraction <- function(numerator = 0, denominator = 1) {
  if (numerator == 0) return(structure(c(0, 1), class = "fraction"))
  if (denominator < 0) {
    numerator <- -numerator
    denominator <- -denominator
  }
  a <- abs(numerator)
  b <- denominator
  while (b != 0) {
    remainder <- a %% b
    a <- b
    b <- remainder
  }
  structure(c(numerator / a, denominator / a), class = "fraction")
}
q_num <- function(value) unclass(value)[[1L]]
q_den <- function(value) unclass(value)[[2L]]
as_fraction <- function(value) if (inherits(value, "fraction")) value else fraction(value)
Ops.fraction <- function(e1, e2) {
  e1 <- as_fraction(e1)
  a <- q_num(e1)
  b <- q_den(e1)
  if (missing(e2)) return(if (.Generic == "-") fraction(-a, b) else e1)
  e2 <- as_fraction(e2)
  c <- q_num(e2)
  d <- q_den(e2)
  switch(.Generic,
         "+" = fraction(a * d + c * b, b * d),
         "-" = fraction(a * d - c * b, b * d),
         "*" = fraction(a * c, b * d),
         "/" = fraction(a * d, b * c),
         "==" = a * d == c * b,
         "!=" = a * d != c * b,
         "<" = a * d < c * b,
         ">" = a * d > c * b,
         "<=" = a * d <= c * b,
         ">=" = a * d >= c * b)
}
ZERO <- fraction()
qsum <- function(values) Reduce(`+`, values, init = ZERO)
